 it('three independent burns, each tier and single non-stacking claim',async()=>{for(let target=1;target<=3;target++){const a=new MockAdapter(0);a.reset();await tx(a,'play');for(let tier=1;tier<=target;tier++){a.supplyNextTier();await tx(a,'play');if(tier<target)await tx(a,'continueChallenge');}expect((await a.getRewardState(a.address)).amount).toBe([1_000_000n,10_000_000n,100_000_000n][target-1]*unit);await tx(a,'claimReward');expect(await a.getTokenBalance(a.address)).toBe([1_000_000n,10_000_000n,100_000_000n][target-1]*unit);await expect(tx(a,'claimReward')).rejects.toThrow();}});
