import '@testing-library/jest-dom/vitest';
import {cleanup} from '@testing-library/react';
import {afterEach,beforeEach} from 'vitest';
afterEach(cleanup);beforeEach(()=>localStorage.clear());

import {useCallback,useEffect,useRef,useState} from 'react';
import type {Action,GameState,NFTCollection,RewardState,Status,ThreeShapeAdapter,TransactionResult} from '../contracts/types';
interface Snapshot {game:GameState;collection:NFTCollection;reward:RewardState;balance:bigint}
export function useThreeShape(adapter:ThreeShapeAdapter,addressProp:string|null|undefined,live:boolean){
 const [address,setAddress]=useState<string|null>(addressProp??null),[status,setStatus]=useState<Status>('disconnected'),[snapshot,setSnapshot]=useState<Snapshot|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[hash,setHash]=useState<string>();
 const epoch=useRef(0),locked=useRef(false),current=useRef<string|null>(addressProp??null);
 const key=(a:string)=>'three-shape-preview-pending:'+a.toLowerCase();
 const reload=useCallback(async(a:string,ticket:number)=>{
  if(live){const pending=localStorage.getItem(key(a));if(pending){if(!adapter.recoverPending)throw new Error('存在待核实交易，需要接入恢复接口后才能继续');const tx=await adapter.recoverPending(a,JSON.parse(pending).hash);if(tx){const receipt=await tx.wait(2);localStorage.removeItem(key(a));if(!receipt.success)throw new Error(receipt.message??'待处理交易失败');}else localStorage.removeItem(key(a));}}
  const [game,collection,reward,balance]=await Promise.all([adapter.getGameState(a),adapter.getCollection(a),adapter.getRewardState(a),adapter.getTokenBalance(a)]);
  if(ticket!==epoch.current)return;
  setSnapshot({game,collection,reward,balance});setStatus(reward.claimed?'claimed':reward.eligible?'reward_available':game.freeClaimed?'result':'ready');
 },[adapter,live]);
 const change=useCallback((a:string|null)=>{
  const ticket=++epoch.current;current.current=a;locked.current=Boolean(a);setAddress(a);setSnapshot(null);setError('');setHash(undefined);setBusy(Boolean(a));setStatus(a?'ready':'disconnected');
  if(a)void reload(a,ticket).catch(e=>{if(ticket===epoch.current){setStatus('error');setError(e instanceof Error?e.message:String(e));}}).finally(()=>{if(ticket===epoch.current){locked.current=false;setBusy(false);}});
 },[reload]);
 useEffect(()=>{change(addressProp??null);return()=>{++epoch.current;};},[addressProp,change]);
 useEffect(()=>adapter.subscribe?.(s=>change(s.address)),[adapter,change]);
 const connect=async()=>{if(locked.current)return;locked.current=true;setBusy(true);const ticket=epoch.current;try{const a=await adapter.connectWallet();if(ticket===epoch.current)change(a);}catch(e){if(ticket===epoch.current){setStatus('error');setError(e instanceof Error?e.message:String(e));}}finally{if(ticket===epoch.current){locked.current=false;setBusy(false);}}};
 const refresh=async()=>{if(locked.current||!current.current)return;locked.current=true;setBusy(true);setError('');const ticket=epoch.current;try{await reload(current.current,ticket);}catch(e){if(ticket===epoch.current){setStatus('error');setError(e instanceof Error?e.message:String(e));}}finally{if(ticket===epoch.current){locked.current=false;setBusy(false);}}};
 const execute=async(name:Action|'buyStars',task:()=>Promise<TransactionResult>)=>{
  const a=current.current;if(locked.current||!a||!snapshot)return;
  if(!snapshot.game.eligible){setError('此钱包未持有 .ai ID');return;}
  if(live&&localStorage.getItem(key(a))){setError('请先恢复待核实交易');return;}
  const ticket=epoch.current;locked.current=true;setBusy(true);setError('');setHash(undefined);setStatus(name==='claimReward'?'claiming':'playing');let known=false;
  try{
   if(live)localStorage.setItem(key(a),JSON.stringify({action:name}));
   const tx=await task();if(live)localStorage.setItem(key(a),JSON.stringify({action:name,hash:tx.hash}));
   if(ticket===epoch.current){setHash(tx.hash);setStatus('confirming');}
   const receipt=await tx.wait(live?2:1);known=true;if(live)localStorage.removeItem(key(a));
   if(!receipt.success)throw new Error(receipt.message??'交易执行失败');
   if(ticket===epoch.current)await reload(a,ticket);
  }catch(e){if(live&&!known&&e&&typeof e==='object'&&'code'in e&&e.code===4001)localStorage.removeItem(key(a));if(ticket===epoch.current){setStatus('error');setError(e instanceof Error?e.message:String(e));}}
  finally{if(ticket===epoch.current){locked.current=false;setBusy(false);}}
 };
 const act=async(action:Action)=>{if(!snapshot)return;const allowed=action==='play'?snapshot.game.canPlay:action==='claimReward'?snapshot.reward.eligible:snapshot.game.canContinue;if(allowed)await execute(action,()=>adapter[action]());};
 const disconnect=async()=>{change(null);try{await adapter.disconnect?.();}catch(e){setError(e instanceof Error?e.message:String(e));}};
 return {address,status,snapshot,error,busy,hash,connect,refresh,act,execute,disconnect};
}

export type Mode='mock'|'live';
export type Action='play'|'continueChallenge'|'claimReward';
export type Status='disconnected'|'ready'|'playing'|'confirming'|'result'|'reward_available'|'claiming'|'claimed'|'error';
export interface NFTItem {type:number;name:string;emoji:string;quantity:bigint;tokenIds:string[];metadata:Record<string,unknown>;contractAddress?:string}
export type NFTCollection=NFTItem[];
export interface GameState {tier:1|2|3;phase:'ready'|'choice'|'settled';freeClaimed:boolean;eligible:boolean;canPlay:boolean;canContinue:boolean;result:string[]|null;globalStage:number;remainingShares:number;starsSold:number;starsBought:number;rewardTiers:bigint[];message:string}
export interface RewardState {eligible:boolean;claimed:boolean;amount:bigint}
export interface TransactionResult {hash?:string;wait(confirmations:number):Promise<{success:boolean;message?:string}>}
export interface PlayPreview {kind:'free'|'burn';tokenIds:string[];warning:string;address:string}
export interface WalletSession {address:string|null;chainId:string}
export interface StarQuote {quantity:number;payment:bigint;address:string}
export interface ThreeShapeAdapter {
 readonly tokenDecimals?:number;
 readonly usdtDecimals?:number;
 connectWallet():Promise<string>;
 getGameState(address:string):Promise<GameState>;
 getCollection(address:string):Promise<NFTCollection>;
 getRewardState(address:string):Promise<RewardState>;
 play():Promise<TransactionResult>;
 claimReward():Promise<TransactionResult>;
 continueChallenge():Promise<TransactionResult>;
 getTokenBalance(address:string):Promise<bigint>;
 preparePlay?(address:string):Promise<PlayPreview>;
 quoteStars?(address:string,quantity:number):Promise<StarQuote>;
 buyStars?(quote:StarQuote):Promise<TransactionResult>;
 subscribe?(fn:(session:WalletSession)=>void):()=>void;
 disconnect?():Promise<void>;
 recoverPending?(address:string,hash?:string):Promise<TransactionResult|null>;
}

